class Traveller {
  +name : string
  +companyName : string
  +address : string
  +travelPreferences : string[]
  +reliabilityRating : float
}

class BillingInformation {
  +companyName : string
  +address : string
}

class SearchCriteria {
  +city : string
  +arrivalDate : date
  +departureDate : date
  +numberOfRooms : int
  +roomType : string
  +minimumHotelRating : int
  +maxCostPerNight : float
  +furtherPreferences : string[]
}

class PreliminaryBooking {
  +bookingIdentifier : string
  +price : float
  +cityArea : string
  +hotelRating : int
  +keyPreferences : string[]
}

class Booking {
  +cancellationDeadline : date
}

class PrePaidBooking extends Booking {}
class PaidAtHotelBooking extends Booking {}

class SpecialOffer {
  +price : float
}

class Hotel {
  +name : string
  +address : string
  +rating : int
}

class HotelChain {
  +name : string
}

class RoomType {
  +type : string
}

class Availability {
  +isFullyBooked : boolean
}

class CreditCardInformation {
  +cardNumber : string
  +expiryDate : date
}

Traveller "1" -- "1" BillingInformation : has
Traveller "1" -- "*" PreliminaryBooking : creates
