Traveller "1" -- "*" SpecialOffer : receives
Traveller "1" -- "1" CreditCardInformation : provides

PreliminaryBooking "*" -- "1" Traveller : relates to
PreliminaryBooking "*" -- "*" Hotel : forwarded to

Hotel "1" -- "*" HotelChain : run by
Hotel "1" -- "*" RoomType : announces
Hotel "1" -- "*" Availability : manages
Hotel "1" -- "*" Booking : confirms
Hotel "1" -- "*" SpecialOffer : provides

Hotel "1" -- "1" Availability : has
RoomType "1" -- "*" Availability : defines

Booking "1" -- "1" Hotel : confirmed by
Booking "1" -- "1" RoomType : involves

@enduml

